const $=id=>document.getElementById(id);
const W=1000,H=560,FLOOR=500,GRAVITY=.18,HOOP={x:794,y:218};
const skins=[{name:'Classic Orange',emoji:'🏀',at:1,color:'#f47b35'},{name:'Street Legend',emoji:'🏀',at:3,color:'#ff5d43'},{name:'Neon Volt',emoji:'🟡',at:5,color:'#d8fa58'},{name:'Deep Space',emoji:'🟣',at:8,color:'#9e76ff'}];
const titles=['Rookie','Sixth Player','Starter','All-Star','MVP','Franchise','Hall of Fame','Legend'];
const load=()=>{try{return JSON.parse(localStorage.getItem('fullCourtSave'))||{}}catch{return {}}};
const saved=load();
const state={career:Math.max(1,saved.career||1),xp:saved.xp||0,coins:saved.coins||0,totalMakes:saved.totalMakes||0,totalShots:saved.totalShots||0,bestStreak:saved.bestStreak||0,streak:saved.streak||0,skin:saved.skin||0,round:1,makes:0,attempts:0,results:[],balls:[],particles:[],aim:null,launchX:260,launchY:478,shotTimer:0,roundDone:false,roundWon:false,toastTimer:0,sound:true,muted:false};
let audio=null,lastFrame=0;
function save(){try{localStorage.setItem('fullCourtSave',JSON.stringify({career:state.career,xp:state.xp,coins:state.coins,totalMakes:state.totalMakes,totalShots:state.totalShots,bestStreak:state.bestStreak,streak:state.streak,skin:state.skin}))}catch{}}
function level(){return Math.floor(state.xp/100)+1}
function levelXP(){return state.xp%100}
function showToast(text){const e=$('toast');e.textContent=text;e.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>e.classList.remove('show'),2100)}
function beep(freq=520,dur=.1,type='sine'){if(!state.sound||state.muted)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.08,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch{}}
function updateUI(){
 $('coinTop').textContent=state.coins;$('roundMakes').textContent=state.makes;$('roundNum').textContent=`ROUND ${String(state.round).padStart(2,'0')}`;
 $('roundName').textContent=state.career===1?'ROOKIE RUN':state.career<4?'CITY LEAGUE':state.career<8?'PRO CIRCUIT':'LEGENDS TOUR';
 $('levelNumber').textContent=String(level()).padStart(2,'0');$('levelTitle').textContent=titles[Math.min(titles.length-1,level()-1)];
 $('xpFill').style.width=`${levelXP()}%`;$('xpText').textContent=`${levelXP()} XP`;$('xpNext').textContent=`${level()*100} XP`;
 $('objective').textContent=state.roundDone?(state.roundWon?'Round cleared!':'Round not cleared'):'Sink 3 of 5 shots';
 $('objectiveSub').textContent=state.roundDone?(state.roundWon?'Your next challenge is ready.':'You need 3 makes. Give it another go!'):'Make it count. Every basket earns XP.';
 $('roundMakes').nextElementSibling.textContent=' / 3';$('targetPill').textContent=state.roundDone?(state.roundWon?'✓ ROUND CLEAR':'↻ TRY AGAIN'):'🎯 3 TO ADVANCE';
 $('streakNum').textContent=state.streak;$('bestStreak').textContent=state.bestStreak;$('soundBtn').textContent=state.muted?'◖×)':'◖))';
 const steps=$('progressSteps');steps.innerHTML='';for(let i=1;i<=8;i++){const s=document.createElement('i');s.className='progress-step'+(i<state.career?' done':i===state.career?' active':'');steps.appendChild(s)}
 const next=skins.find(s=>level()<s.at)||skins[skins.length-1];$('rewardName').textContent=next.name;$('rewardBall').textContent=next.emoji;$('rewardDesc').textContent=level()>=next.at?'New ball unlocked!':`Unlock at career level ${next.at}`;$('rewardLock').textContent=level()>=next.at?'✓':'🔒';$('rewardLock').classList.toggle('ready',level()>=next.at);$('rewardProgress').style.width=`${Math.min(100,level()/next.at*100)}%`;
 const dots=$('shotDots');dots.innerHTML='';for(let i=0;i<5;i++){const d=document.createElement('div');d.className='shot-dot'+(state.results[i]===true?' made':state.results[i]===false?' missed':i===state.attempts&&!state.roundDone?' current':'');d.textContent=state.results[i]===true?'✓':state.results[i]===false?'×':i+1;dots.appendChild(d)}
 $('footStatus').innerHTML=state.roundDone?(state.roundWon?'<strong>Round won!</strong> Claim your next challenge.':'<strong>Not quite.</strong> Retry this round to advance.'):(state.aim?'Release to shoot!':'Drag from the ball to line up your shot.');
}
function currentSkin(){return skins[Math.min(state.skin,skins.length-1)]}
function spawn(){state.balls=[];state.launchX=Math.max(210,260-Math.min(5,state.career-1)*23);state.launchY=478;state.aim=null}
function roundReset(){state.attempts=0;state.makes=0;state.results=[];state.roundDone=false;state.roundWon=false;state.balls=[];state.streak=0;spawn();updateUI()}

