function roundReset(){state.attempts=0;state.makes=0;state.results=[];state.roundDone=false;state.roundWon=false;state.balls=[];state.streak=0;spawn();updateUI()}
function rr(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function drawCourt(){
 const sky=ctx.createLinearGradient(0,0,0,360);sky.addColorStop(0,'#1c2921');sky.addColorStop(.7,'#263329');sky.addColorStop(1,'#394331');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 // gym wall panels and high windows
 ctx.fillStyle='#19241e';ctx.fillRect(0,0,W,110);
 for(let i=0;i<7;i++){const x=35+i*145;rr(x,20,94,58,5,'#314137','#48564a');ctx.fillStyle='#a5d6bd';ctx.globalAlpha=.22;ctx.fillRect(x+5,25,84,48);ctx.globalAlpha=1;ctx.fillStyle='#526254';ctx.fillRect(x+45,23,3,52)}
 // distant crowd / bleachers
 ctx.fillStyle='#374337';ctx.fillRect(0,112,W,180);ctx.fillStyle='#263229';ctx.fillRect(0,112,W,9);
 for(let row=0;row<3;row++){ctx.fillStyle=['#4b5845','#3b4839','#303d32'][row];ctx.fillRect(0,142+row*42,W,7);for(let i=0;i<48;i++){const x=i*23+(row%2)*11,y=126+row*42;ctx.fillStyle=['#d87651','#d7bb79','#718d73','#798ca1','#b07e72'][(i*7+row*3)%5];ctx.globalAlpha=.28+((i*3+row)%5)*.09;ctx.beginPath();ctx.arc(x+5,y+5,3+(i%3===0?1:0),0,Math.PI*2);ctx.fill();ctx.fillRect(x+2,y+9,7,10)}ctx.globalAlpha=1}
 // arena signage
 rr(413,114,170,28,5,'#17231b','#435344');ctx.fillStyle='#d3f36b';ctx.font='800 11px "DM Sans"';ctx.textAlign='center';ctx.fillText('HOME OF THE HUSTLE',498,132);
 // court plane
 const floor=ctx.createLinearGradient(0,290,0,H);floor.addColorStop(0,'#6d6847');floor.addColorStop(.24,'#c38d51');floor.addColorStop(1,'#a96f3d');ctx.fillStyle=floor;ctx.beginPath();ctx.moveTo(0,288);ctx.lineTo(W,288);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.closePath();ctx.fill();
 // board seams perspective
 ctx.globalAlpha=.16;ctx.strokeStyle='#ffe0a2';ctx.lineWidth=2;for(let i=0;i<=12;i++){let x=i*95;ctx.beginPath();ctx.moveTo(x,289);ctx.lineTo(x+(x-500)*.15,H);ctx.stroke()}for(let y=333;y<560;y+=44){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.globalAlpha=1;
 // key, arc, baseline & center lines
 ctx.strokeStyle='#f2d5a5';ctx.globalAlpha=.67;ctx.lineWidth=3;ctx.strokeRect(HOOP.x-225,288,225,212);ctx.beginPath();ctx.arc(HOOP.x-225,394,106,-Math.PI/2,Math.PI/2);ctx.stroke();ctx.beginPath();ctx.arc(HOOP.x,394,365,Math.PI*.53,Math.PI*1.47);ctx.stroke();ctx.beginPath();ctx.moveTo(0,500);ctx.lineTo(W,500);ctx.stroke();ctx.globalAlpha=1;
 // shooting spot marker
 ctx.fillStyle='#e2f57a';ctx.globalAlpha=.6;ctx.beginPath();ctx.arc(state.launchX,499,4,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
 // floor gleam
 const glow=ctx.createRadialGradient(HOOP.x,425,5,HOOP.x,425,210);glow.addColorStop(0,'#f3d18922');glow.addColorStop(1,'#f3d18900');ctx.fillStyle=glow;ctx.fillRect(500,270,500,290);
}
function drawHoop(){
 // backboard pole & board
 ctx.fillStyle='#303c35';ctx.fillRect(879,179,12,322);ctx.fillStyle='#9ca99e';ctx.fillRect(873,144,6,365);rr(824,148,74,62,4,'#e2e8dd','#f5f5e9');ctx.fillStyle='#b8c2b5';ctx.fillRect(832,156,58,46);ctx.strokeStyle='#d55b38';ctx.lineWidth=3;ctx.strokeRect(846,174,28,22);
 // rim
 ctx.strokeStyle='#ec6944';ctx.lineWidth=7;ctx.beginPath();ctx.ellipse(HOOP.x+15,HOOP.y,30,7,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#e9724a';ctx.fillRect(HOOP.x-18,HOOP.y-3,36,6);
 // net
 ctx.strokeStyle='#e7e5d5';ctx.lineWidth=1.4;ctx.globalAlpha=.72;ctx.beginPath();ctx.moveTo(HOOP.x-17,HOOP.y+5);ctx.lineTo(HOOP.x-10,HOOP.y+44);ctx.lineTo(HOOP.x+9,HOOP.y+44);ctx.lineTo(HOOP.x+18,HOOP.y+5);ctx.stroke();for(let i=0;i<5;i++){const x=HOOP.x-14+i*7;ctx.beginPath();ctx.moveTo(x,HOOP.y+7);ctx.lineTo(HOOP.x-8+i*4,HOOP.y+43);ctx.stroke()}for(let j=1;j<=3;j++){const y=HOOP.y+10+j*8;ctx.beginPath();ctx.moveTo(HOOP.x-16+j*1.5,y);ctx.lineTo(HOOP.x+16-j*1.5,y);ctx.stroke()}ctx.globalAlpha=1;
}
function drawPlayer(){
 const x=state.launchX-47,y=FLOOR;
 // shadow
 ctx.fillStyle='#33271e66';ctx.beginPath();ctx.ellipse(x+7,y-1,36,8,0,0,Math.PI*2);ctx.fill();
 // legs / shoes
 ctx.fillStyle='#292d29';ctx.beginPath();ctx.moveTo(x-15,y-49);ctx.lineTo(x-1,y-46);ctx.lineTo(x-5,y-7);ctx.lineTo(x-18,y-5);ctx.fill();ctx.beginPath();ctx.moveTo(x+2,y-46);ctx.lineTo(x+16,y-48);ctx.lineTo(x+21,y-7);ctx.lineTo(x+8,y-6);ctx.fill();rr(x-23,y-9,24,8,4,'#e7e7db');rr(x+6,y-9,22,8,4,'#e7e7db');
 // jersey torso
 ctx.fillStyle='#e7653c';ctx.beginPath();ctx.moveTo(x-19,y-105);ctx.quadraticCurveTo(x,y-116,x+20,y-104);ctx.lineTo(x+17,y-47);ctx.quadraticCurveTo(x,y-41,x-17,y-48);ctx.closePath();ctx.fill();ctx.fillStyle='#f7e7c1';ctx.fillRect(x-19,y-59,36,5);ctx.fillStyle='#ffe9cb';ctx.font='800 18px "Barlow Condensed"';ctx.textAlign='center';ctx.fillText('7',x,y-73);
 // arms holding pose
 ctx.strokeStyle='#c68157';ctx.lineWidth=11;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(x-15,y-96);ctx.lineTo(x-30,y-79);ctx.lineTo(state.launchX-6,state.launchY+2);ctx.stroke();ctx.beginPath();ctx.moveTo(x+14,y-97);ctx.lineTo(x+29,y-79);ctx.lineTo(state.launchX+5,state.launchY+1);ctx.stroke();
 // neck / head
 ctx.fillStyle='#be8059';ctx.fillRect(x-6,y-116,13,13);ctx.fillStyle='#bd7954';ctx.beginPath();ctx.arc(x,y-130,17,0,Math.PI*2);ctx.fill();ctx.fillStyle='#20251f';ctx.beginPath();ctx.arc(x,y-137,17,Math.PI,Math.PI*2);ctx.lineTo(x+15,y-128);ctx.quadraticCurveTo(x,y-135,x-16,y-128);ctx.fill();ctx.fillStyle='#f5d0ae';ctx.beginPath();ctx.arc(x+6,y-131,1.3,0,Math.PI*2);ctx.fill();ctx.lineCap='butt';
}

