function render(){ctx.clearRect(0,0,W,H);drawCourt();drawHoop();drawPlayer();drawAim();for(const b of state.balls)drawBall(b);drawParticles();drawOverlay()}
function burst(x,y,color,n=18){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=1+Math.random()*4;state.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-2,life:35+Math.random()*20,max:55,r:2+Math.random()*3,color})}}
function recordMake(b){if(b.scored)return;b.scored=true;state.results[b.index]=true;state.makes++;state.totalMakes++;state.streak++;state.bestStreak=Math.max(state.streak,state.bestStreak);const points=22+Math.min(18,state.streak*4);state.xp+=points;state.coins+=3+Math.min(7,state.streak);state.totalShots++;const oldLevel=level();state.skin=Math.min(skins.length-1,Math.max(state.skin,skins.findIndex(s=>s.at>level())-1));if(state.skin<0)state.skin=0;burst(HOOP.x,HOOP.y,'#eaf6a1',24);beep(680,.12);setTimeout(()=>beep(910,.16),100);showToast(state.streak>=3?`🔥 ${state.streak} IN A ROW! +${points} XP`:`BUCKET! +${points} XP`);if(level()>oldLevel)showToast(`LEVEL UP! ${titles[Math.min(level()-1,titles.length-1)]}`);updateUI()}
function recordMiss(b){if(b.resolved)return;b.resolved=true;state.results[b.index]=false;state.streak=0;state.totalShots++;beep(155,.18,'triangle');updateUI()}
function finishRound(){if(state.roundDone)return;state.roundDone=true;state.roundWon=state.makes>=3;if(state.roundWon){state.coins+=25;state.xp+=35;state.skin=Math.max(state.skin,Math.min(skins.length-1,skins.findLastIndex?skins.findLastIndex(s=>level()>=s.at):0));showToast('ROUND WON! +25 coins · +35 XP');beep(740,.2);setTimeout(()=>beep(990,.25),160)}else showToast('Need 3 makes to advance. Try again!');save();updateUI()}
function advanceRound(){if(!state.roundDone)return;if(state.roundWon){state.career++;state.round++}roundReset();showToast(state.roundWon?'New round — keep the streak alive!':'You got this. Take your time on the arc.');save()}
function launch(params){if(state.balls.length||state.roundDone||state.attempts>=5)return;const b={x:state.launchX,y:state.launchY,vx:params.vx,vy:params.vy,rot:0,skin:{...currentSkin()},index:state.attempts,frames:0,scored:false,resolved:false,remove:false,bounces:0};state.attempts++;state.balls.push(b);state.aim=null;beep(260,.07,'triangle');updateUI()}
function defaultParams(){const a=.875,speed=13.1;return{a,speed,vx:speed*Math.cos(a),vy:-speed*Math.sin(a)}}
function frame(t){const dt=Math.min(2,(t-lastFrame)/16.67||1);lastFrame=t;
 for(const b of state.balls){if(b.remove)continue;b.frames+=dt;b.x+=b.vx*dt;b.y+=b.vy*dt;b.vy+=GRAVITY*dt;b.vx*=Math.pow(.999,dt);b.rot+=b.vx*.012*dt;
  if(!b.scored&&!b.resolved&&b.x>=HOOP.x-3&&b.x-b.vx*dt<HOOP.x-3){const ratio=(HOOP.x-3-(b.x-b.vx*dt))/Math.max(.01,b.vx*dt),cy=b.y-b.vy*dt*ratio;if(cy>HOOP.y-22&&cy<HOOP.y+23)recordMake(b);else if(cy>HOOP.y+23&&b.vy>0)recordMiss(b)}
  if(!b.scored&&b.x>824&&b.x<900&&b.y>144&&b.y<211&&b.vx>0){b.x=824;b.vx=-Math.abs(b.vx)*.58;b.vy*=.65}
  if(b.y>FLOOR-14&&!b.scored){if(!b.resolved)recordMiss(b);b.y=FLOOR-14;if(b.bounces<1){b.vy=-Math.abs(b.vy)*.38;b.vx*=.58;b.bounces++}else b.remove=true}
  if(b.scored&&b.frames>37)b.remove=true;if(b.x>1020||b.frames>190)b.remove=true;
 }
 state.balls=state.balls.filter(b=>!b.remove);for(const p of state.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=.12*dt;p.life-=dt}state.particles=state.particles.filter(p=>p.life>0);
 if(state.attempts>=5&&state.balls.length===0&&!state.roundDone)finishRound();render();requestAnimationFrame(frame)
}
function point(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H}}
let pointerDown=false;
canvas.addEventListener('pointerdown',e=>{e.preventDefault();const p=point(e);if(state.roundDone){if(p.x>380&&p.x<620&&p.y>300&&p.y<380)advanceRound();return}if(state.balls.length||state.attempts>=5)return;const d=Math.hypot(p.x-state.launchX,p.y-state.launchY);if(d<62){pointerDown=true;state.aim={x:state.launchX+105,y:state.launchY-125};canvas.setPointerCapture(e.pointerId);render()}});
canvas.addEventListener('pointermove',e=>{if(pointerDown){e.preventDefault();const p=point(e);state.aim={x:p.x,y:p.y};render()}});
canvas.addEventListener('pointerup',e=>{if(!pointerDown)return;e.preventDefault();pointerDown=false;const p=state.aim?aimParams():null;if(p&&p.speed>8.7)launch(p);else state.aim=null});
canvas.addEventListener('pointercancel',()=>{pointerDown=false;state.aim=null});
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' ','Enter'].includes(e.key))e.preventDefault();if(state.roundDone&&(e.key===' '||e.key==='Enter')){advanceRound();return}if(e.key===' '){if(!state.balls.length)launch(state.aim?aimParams():defaultParams());return}if(e.key==='ArrowLeft'||e.key==='ArrowRight'){if(state.balls.length||state.roundDone)return;if(!state.aim)state.aim={x:state.launchX+100,y:state.launchY-130};let p=aimParams(),a=p.a+(e.key==='ArrowRight'?.035:-.035);a=Math.max(.38,Math.min(1.33,a));state.aim={x:state.launchX+Math.cos(a)*140,y:state.launchY-Math.sin(a)*140};render()}});
$('advanceBtn').addEventListener('click',advanceRound);
$('soundBtn').addEventListener('click',()=>{state.muted=!state.muted;$('soundBtn').textContent=state.muted?'◖×)':'◖))';if(!state.muted)beep(560,.08)});
$('howBtn').addEventListener('click',()=>$('modal').classList.add('open'));$('modalClose').addEventListener('click',()=>$('modal').classList.remove('open'));$('modal').addEventListener('click',e=>{if(e.target===$('modal'))$('modal').classList.remove('open')});
$('resetBtn').addEventListener('click',()=>{if(confirm('Start a new career? Your current career progress will be erased.')){localStorage.removeItem('fullCourtSave');Object.assign(state,{career:1,xp:0,coins:0,totalMakes:0,totalShots:0,bestStreak:0,streak:0,skin:0,round:1});roundReset();showToast('A fresh career begins!')}});
function syncAdvance(){const b=$('advanceBtn');b.style.display=state.roundDone?'block':'none';b.textContent=state.roundWon?'NEXT ROUND →':'RETRY ROUND ↻'}
const originalUpdateUI=updateUI; // refresh the round action after each state change
updateUI=function(){originalUpdateUI();syncAdvance()};
updateUI();spawn();requestAnimationFrame(frame);
})();
</script>
</body>
</html>

